arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Application
cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Gold
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotalHandler.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotal(CustomerTier Tier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotal command) => command.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Application/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Application;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_a_100_00_subtotal_pays_95_00()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotal(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -25

